-- Coding problems, test cases and submissions (problem rows: npm run coding:import).
-- Tables: cdng_prblm_lst_t, cdng_tst_cs_lst_t, cdng_sbmsn_dtl_t
-- Generated by server/scripts/export-sql.mjs from the migrated database. Run the files in numeric order on an empty database.

BEGIN;

CREATE TABLE public.cdng_prblm_lst_t (
    cdng_prblm_id text NOT NULL,
    college_id text,
    prblm_slug_tx text NOT NULL,
    prblm_ttl text NOT NULL,
    difficulty_cd public."Difficulty" DEFAULT 'EASY'::public."Difficulty" NOT NULL,
    topic_tx text DEFAULT ''::text NOT NULL,
    statement_tx text NOT NULL,
    input_format_tx text DEFAULT ''::text NOT NULL,
    output_format_tx text DEFAULT ''::text NOT NULL,
    constraints_tx text DEFAULT ''::text NOT NULL,
    time_limit_ms_ct integer DEFAULT 2000 NOT NULL,
    sqnce_id integer DEFAULT 0 NOT NULL,
    i_ts timestamp(3) without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    u_ts timestamp(3) without time zone,
    crte_usr_id text,
    updte_usr_id text,
    a_in smallint DEFAULT 1 NOT NULL,
    d_ts timestamp(3) without time zone,
    checker_cd public."CheckerMode" DEFAULT 'TRIMMED'::public."CheckerMode" NOT NULL,
    epsilon_ct double precision DEFAULT 0.000001 NOT NULL,
    languages_json jsonb,
    max_score_ct double precision DEFAULT 100 NOT NULL,
    memory_limit_mb_ct integer DEFAULT 256 NOT NULL,
    reference_lang_cd text,
    reference_solution_tx text,
    scoring_cd public."ScoringMode" DEFAULT 'WEIGHTED'::public."ScoringMode" NOT NULL,
    status_cd public."ProblemStatus" DEFAULT 'DRAFT'::public."ProblemStatus" NOT NULL,
    validated_ts timestamp(3) without time zone,
    visibility_cd public."CodingVisibility" DEFAULT 'PRACTICE'::public."CodingVisibility" NOT NULL,
    CONSTRAINT cdng_prblm_lst_t_judge_check CHECK ((((memory_limit_mb_ct >= 16) AND (memory_limit_mb_ct <= 2048)) AND (epsilon_ct >= (0)::double precision) AND (max_score_ct > (0)::double precision))),
    CONSTRAINT cdng_prblm_lst_t_values_check CHECK ((((time_limit_ms_ct >= 100) AND (time_limit_ms_ct <= 20000)) AND (a_in = ANY (ARRAY[0, 1]))))
);

CREATE TABLE public.cdng_sbmsn_dtl_t (
    cdng_sbmsn_id text NOT NULL,
    college_id text NOT NULL,
    user_id text NOT NULL,
    cdng_prblm_id text NOT NULL,
    lang_cd text NOT NULL,
    code_tx text NOT NULL,
    status_cd public."SubmissionStatus",
    passed_ct integer DEFAULT 0 NOT NULL,
    total_ct integer DEFAULT 0 NOT NULL,
    runtime_ms_ct integer DEFAULT 0 NOT NULL,
    results_json jsonb,
    i_ts timestamp(3) without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    atmpt_id text,
    custom_input_tx text,
    job_status_cd public."JudgeStatus" DEFAULT 'QUEUED'::public."JudgeStatus" NOT NULL,
    judged_ts timestamp(3) without time zone,
    kind_cd public."SubmissionKind" DEFAULT 'SUBMIT'::public."SubmissionKind" NOT NULL,
    limits_json jsonb,
    max_score_ct double precision DEFAULT 0 NOT NULL,
    qstn_id text,
    score_ct double precision,
    started_ts timestamp(3) without time zone,
    tries_ct integer DEFAULT 0 NOT NULL,
    worker_tx text,
    CONSTRAINT cdng_sbmsn_dtl_t_counts_check CHECK (((passed_ct >= 0) AND (passed_ct <= total_ct))),
    CONSTRAINT cdng_sbmsn_dtl_t_tries_check CHECK ((tries_ct >= 0))
);

CREATE TABLE public.cdng_tst_cs_lst_t (
    cdng_tst_cs_id text NOT NULL,
    cdng_prblm_id text NOT NULL,
    input_tx text NOT NULL,
    expected_output_tx text NOT NULL,
    is_sample_in smallint DEFAULT 0 NOT NULL,
    sqnce_id integer DEFAULT 0 NOT NULL,
    i_ts timestamp(3) without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    explanation_tx text DEFAULT ''::text NOT NULL,
    group_tx text DEFAULT ''::text NOT NULL,
    weight_ct double precision DEFAULT 1 NOT NULL,
    CONSTRAINT cdng_tst_cs_lst_t_sample_check CHECK ((is_sample_in = ANY (ARRAY[0, 1]))),
    CONSTRAINT cdng_tst_cs_lst_t_weight_check CHECK ((weight_ct >= (0)::double precision))
);

ALTER TABLE ONLY public.cdng_prblm_lst_t
    ADD CONSTRAINT cdng_prblm_lst_t_pkey PRIMARY KEY (cdng_prblm_id);

ALTER TABLE ONLY public.cdng_sbmsn_dtl_t
    ADD CONSTRAINT cdng_sbmsn_dtl_t_pkey PRIMARY KEY (cdng_sbmsn_id);

ALTER TABLE ONLY public.cdng_tst_cs_lst_t
    ADD CONSTRAINT cdng_tst_cs_lst_t_pkey PRIMARY KEY (cdng_tst_cs_id);

CREATE INDEX cdng_prblm_lst_t_college_id_idx ON public.cdng_prblm_lst_t USING btree (college_id);

CREATE UNIQUE INDEX cdng_prblm_lst_t_prblm_slug_tx_key ON public.cdng_prblm_lst_t USING btree (prblm_slug_tx);

CREATE INDEX cdng_sbmsn_dtl_t_atmpt_id_idx ON public.cdng_sbmsn_dtl_t USING btree (atmpt_id);

CREATE INDEX cdng_sbmsn_dtl_t_college_id_idx ON public.cdng_sbmsn_dtl_t USING btree (college_id);

CREATE INDEX cdng_sbmsn_dtl_t_job_status_cd_i_ts_idx ON public.cdng_sbmsn_dtl_t USING btree (job_status_cd, i_ts);

CREATE INDEX cdng_sbmsn_dtl_t_user_id_cdng_prblm_id_idx ON public.cdng_sbmsn_dtl_t USING btree (user_id, cdng_prblm_id);

CREATE INDEX cdng_tst_cs_lst_t_cdng_prblm_id_idx ON public.cdng_tst_cs_lst_t USING btree (cdng_prblm_id);

CREATE TRIGGER cdng_prblm_lst_t_audit_timestamps BEFORE UPDATE ON public.cdng_prblm_lst_t FOR EACH ROW EXECUTE FUNCTION public.campus_set_audit_timestamps();

-- Foreign keys
ALTER TABLE ONLY public.cdng_sbmsn_dtl_t
    ADD CONSTRAINT cdng_sbmsn_dtl_t_cdng_prblm_id_fkey FOREIGN KEY (cdng_prblm_id) REFERENCES public.cdng_prblm_lst_t(cdng_prblm_id) ON UPDATE CASCADE ON DELETE RESTRICT;

ALTER TABLE ONLY public.cdng_tst_cs_lst_t
    ADD CONSTRAINT cdng_tst_cs_lst_t_cdng_prblm_id_fkey FOREIGN KEY (cdng_prblm_id) REFERENCES public.cdng_prblm_lst_t(cdng_prblm_id) ON UPDATE CASCADE ON DELETE CASCADE;

ALTER TABLE ONLY public.qstn_lst_t
    ADD CONSTRAINT qstn_lst_t_cdng_prblm_id_fkey FOREIGN KEY (cdng_prblm_id) REFERENCES public.cdng_prblm_lst_t(cdng_prblm_id) ON UPDATE CASCADE ON DELETE SET NULL;

COMMIT;
